import {advanceFreeTime} from './free-roam.js';
import {wetWeather} from './weather.js';
export const neighborhoodEventDefs={
 parkNote:{place:'pocketPark',title:'벤치 옆의 악보',text:'벤치 옆에 낱장 악보가 떨어져 있다. 조금 떨어진 곳에서 학생 한 명이 가방을 뒤적인다. 아직 이름은 모른다.',fact:'자취촌 공원 벤치 옆 물품 보관 안내',choices:[['help','주변에 주인이 있는지 물어보고 악보를 건넨다.','“아, 여기 있었네요.” 학생은 악보를 받아 페이지를 맞춘다. 잠깐 곡 이야기를 나눴지만 이름이나 연락처까지 묻지는 않았다.'],['check','주인을 단정하지 않고 공원 관리 안내부터 확인한다.','공원 관리 안내에 적힌 습득물 처리 방법을 확인하고, 악보가 바람에 날리지 않도록 눈에 띄는 자리에 둔다.']]},
 neighborhoodBoxes:{place:'communitySquare',title:'쉼터 앞 빈 상자',text:'주민이 쉼터 앞에 빈 상자를 정리하고 있다. 통로가 좁아져 지나가는 사람들이 잠깐씩 발을 멈춘다.',fact:'주택가 쉼터의 공용 통로 위치',choices:[['help','도움이 필요한지 먼저 묻고 빈 상자를 옮긴다.','어디로 옮겨야 하는지 먼저 물었다. 비워도 되는 자리만 정리하자 벤치 앞 통로가 조금 넓어졌다.'],['route','짐을 건드리지 않고 지나다닐 통로를 함께 확인한다.','상자를 임의로 치우지 않고 지나갈 폭이 남는 쪽을 짚었다. 주민은 그쪽으로 상자를 쌓지 않겠다고 고개를 끄덕인다.']]},
 bridgeSketch:{place:'footbridge',title:'다리 위 짧은 부탁',text:'다리 입구에서 풍경을 스케치하던 학생이 바람에 들리는 종이를 누른다. 잠깐 그림판을 잡아줄 수 있는지 묻는다.',fact:'보행교의 넓은 대기 공간',choices:[['help','통행을 막지 않는 넓은 곳에서 잠깐 그림판을 잡아준다.','난간 옆 넓은 곳으로 자리를 옮겼다. 그림판을 잡아준 사이 학생은 빠르게 선을 마무리한다.'],['talk','바람을 피할 수 있는 쪽을 알려주고 풍경 이야기를 나눈다.','바람이 덜 부는 제방 쪽을 가리켰다. 같은 풍경을 다른 각도에서 보는 이야기를 잠깐 나눴다.']]},
 stopDirections:{place:'busStop',title:'정류장에서 길을 묻는 사람',text:'정류장 노선도 앞에서 누군가 학교 정문 방향을 묻는다. 직접 알아본 만큼만 안내할 수 있을 것 같다.',fact:'정류장에서 정문 상권으로 향하는 보행 신호',choices:[['guide','노선도 옆 보행 안내를 함께 보고 정문 방향을 짚는다.','기억에만 의존하지 않고 보행 안내를 함께 확인했다. 상대는 횡단보도 방향을 다시 확인하고 인사한다.'],['walk','횡단보도 앞까지만 함께 가서 갈림길을 알려준다.','내가 가도 되는 구간까지만 함께 걸었다. 신호를 기다리며 정문 쪽으로 갈라지는 길을 알려준다.']]}
};
export function neighborhoodEventsAt(s,place=s.location){if(s.freeDay?.home||s.clock.minute<720||s.clock.minute+15>1080)return [];return Object.entries(neighborhoodEventDefs).filter(([id,d],i)=>d.place===place&&(s.day+i)%3!==2&&!(d.place==='footbridge'&&wetWeather(s))&&!s.neighborhoodEvents?.records?.[`${s.day}:${id}`]&&!Object.entries(s.neighborhoodEvents?.records??{}).some(([key,r])=>key.endsWith(':'+id)&&r.status==='completed')).map(([id,d])=>({id,...d}));}
export function beginNeighborhoodEvent(state,id){const event=neighborhoodEventsAt(state).find(e=>e.id===id);if(!event)throw new Error('지금 이 장소에서 참여할 수 없는 이벤트입니다.');const s=structuredClone(state);s.neighborhoodEvents??={records:{},active:null};s.neighborhoodEvents.active=id;return s;}
export function neighborhoodEventView(s){return neighborhoodEventsAt(s).find(e=>e.id===s.neighborhoodEvents?.active)??null;}
export function resolveNeighborhoodEvent(state,choiceId){const e=neighborhoodEventView(state);if(!e)throw new Error('시간이나 장소가 바뀌어 지금은 이어갈 수 없습니다.');const choice=e.choices.find(c=>c[0]===choiceId);if(!choice&&choiceId!=='pass')throw new Error('선택할 수 없는 행동입니다.');let s=choice?advanceFreeTime(state,15):structuredClone(state);s.neighborhoodEvents.records[`${state.day}:${e.id}`]={status:choice?'completed':'passed',choice:choiceId,minute:s.clock.minute};s.neighborhoodEvents.active=null;s.lastResult=choice?choice[2]:'이번에는 하던 길을 이어간다.';if(choice){if(!s.known.includes(e.fact))s.known.push(e.fact);s.memory.push(`[${s.day}일차] ${e.title}: ${choice[2]}`);}s.pace={count:0,seen:{}};return s;}
